/** Lookup map of locale code → autonym. */
export const LOCALE_AUTONYMS: ReadonlyMap<string, string> = new Map(LOCALE_AUTONYMS_DATA);

/** Lowercased, hyphen-separated code → canonical LOCALE_AUTONYMS key. */
const CANONICAL_CODES: ReadonlyMap<string, string> = new Map(
  LOCALE_AUTONYMS_DATA.map(([code]) => [code.toLowerCase(), code] as const)
);

/**
 * Find the LOCALE_AUTONYMS key for a locale code, ignoring separator and case
 * (locale tags are case-insensitive): "zh_TW", "zh-tw", "ZH-TW" → "zh-TW".
 * Returns null if CLDR does not list the code; no language-subtag fallback.
 */
export function findLocaleCode(localeCode: string): string | null {
  return CANONICAL_CODES.get(localeCode.replace(/_/g, '-').toLowerCase()) ?? null;
}

/**
 * Get the autonym for a locale code.
 * Falls back to the language subtag ("de_XX" → "Deutsch"), then to the code itself.
 */
export function getLocaleAutonym(localeCode: string): string {
  const code = findLocaleCode(localeCode);
  if (code) return LOCALE_AUTONYMS.get(code)!;

  // Language subtag fallback
  const lang = findLocaleCode(localeCode.split(/[-_]/)[0]);
  if (lang) return LOCALE_AUTONYMS.get(lang)!;

  return localeCode;
}
